<?php require_once __DIR__.'/../src/db.php';$db=db();$db->exec("CREATE TABLE IF NOT EXISTS music_tracks (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,artist TEXT NOT NULL DEFAULT '',file_path TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP)");$tracks=$db->query("SELECT title,artist,file_path FROM music_tracks WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();$panos=$db->query("SELECT * FROM panoramas WHERE published=1 ORDER BY id DESC")->fetchAll();$tours=$db->query("SELECT t.*,(SELECT COUNT(*) FROM tour_scenes s WHERE s.tour_id=t.id) scene_count,(SELECT COALESCE(p.preview,p.image) FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=t.id ORDER BY s.sort_order,s.id LIMIT 1) fallback_cover FROM tours t WHERE t.published=1 ORDER BY t.id DESC")->fetchAll();?>
